"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["71301"],{52589(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.configuracao.modelo_formulario.pressuposto_na_inscricao","status":422,"titulo":"O modelo que serve \xe0 fase de inscri\xe7\xe3o n\xe3o tem pressupostos"},"descricao":{"codigo":"uniplus.configuracao.modelo_formulario.pressuposto_na_inscricao","requisitos":["UNI-REQ-0144"],"oQueAconteceu":["O `conteudo` de um modelo que serve \xe0 fase de inscri\xe7\xe3o (`declaracao.serveAFaseDeInscricao` verdadeiro), enviado na cria\xe7\xe3o (`POST /api/configuracao/admin/modelos-formulario`) ou na atualiza\xe7\xe3o (`PUT /api/configuracao/admin/modelos-formulario/{id}`), traz a lista `pressupostos` com algum item. Pressuposto \xe9 um fato que o modelo recebe da inscri\xe7\xe3o em vez de colet\xe1-lo. A inscri\xe7\xe3o \xe9 o formul\xe1rio que coleta esses dados, e nenhum formul\xe1rio \xe9 respondido antes dela; o formul\xe1rio obrigat\xf3rio da inscri\xe7\xe3o tamb\xe9m n\xe3o reaproveita respostas de outro formul\xe1rio obrigat\xf3rio da mesma fase (UNI-REQ-0144). Um item vazio na lista conta: a lista precisa estar vazia ou ausente.","A recusa vem na lista `errors` da resposta, com `field` igual a `conteudo.pressupostos`, e as verifica\xe7\xf5es de dom\xednio dos pressupostos (item em branco, repetido, tamb\xe9m usado como item do modelo) n\xe3o prosseguem. Ela s\xf3 \xe9 feita depois que o conte\xfado foi lido sem recusa de leitura. A confer\xeancia do conte\xfado contra o cat\xe1logo de fatos roda antes e n\xe3o \xe9 interrompida por esta recusa: a mesma resposta pode trazer, al\xe9m dela, recusas dessa confer\xeancia, como a de um fato desconhecido. Nada \xe9 gravado. Na atualiza\xe7\xe3o, a busca do modelo vem antes das valida\xe7\xf5es de dom\xednio do conte\xfado: com um `{id}` que n\xe3o existe, a resposta \xe9 [modelo de formul\xe1rio n\xe3o encontrado](/erros/uniplus.configuracao.modelo_formulario.nao_encontrado). S\xf3 a leitura do corpo vem antes da busca: campo n\xe3o anul\xe1vel ausente ou nulo (como `nome`) \xe9 recusado com 400, sem c\xf3digo deste cat\xe1logo, mesmo com `{id}` inexistente."],"comoResolver":["Retire os pressupostos do modelo que serve \xe0 fase de inscri\xe7\xe3o e, se um fato \xe9 necess\xe1rio, colete-o como item do pr\xf3prio modelo. Um fato s\xf3 \xe9 pressuposto em modelo de outra fase, que o recebe da inscri\xe7\xe3o."],"ondeAparece":["Cria\xe7\xe3o de um modelo de formul\xe1rio","Atualiza\xe7\xe3o de um modelo de formul\xe1rio"]},"modulo":{"id":"configuracao","nome":"Configura\xe7\xe3o","assunto":"Modelo formulario"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"e5dad467d85ce0f062b88f68241ad834bc540cf0"}}')}}]);